SUMMARIZE tbl;
SUMMARIZE main.tbl;
SUMMARIZE TABLE tbl;
SUMMARIZE TABLE 'data.csv';
SUMMARIZE 'data.csv';
SUMMARIZE SELECT * FROM tbl;
SUMMARIZE FROM tbl;
SUMMARIZE (SELECT i FROM tbl);
SUMMARIZE WITH x AS (SELECT 1 AS a) SELECT * FROM x;
SUMMARIZE VALUES (1), (2);

-- SUMMARIZE as a subquery
SELECT * FROM (SUMMARIZE tbl);
SELECT column_name, null_percentage
FROM (SUMMARIZE SELECT * FROM tbl) AS s
WHERE column_name = 'i';
WITH s AS (SUMMARIZE tbl) SELECT * FROM s;
CREATE TABLE tbl_summary AS SELECT * FROM (SUMMARIZE tbl);
